I'll show you a few approaches for a confirmation modal before deletion.

## Vanilla JavaScript + HTML/CSS

```html
<!DOCTYPE html>
<html>
<head>
  <style>
    .modal {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.5);
      z-index: 1000;
      align-items: center;
      justify-content: center;
    }
    .modal.active {
      display: flex;
    }
    .modal-content {
      background: white;
      padding: 2rem;
      border-radius: 8px;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
      max-width: 400px;
    }
    .modal-buttons {
      display: flex;
      gap: 1rem;
      margin-top: 1.5rem;
      justify-content: flex-end;
    }
    button {
      padding: 0.5rem 1rem;
      border: none;
      border-radius: 4px;
      cursor: pointer;
    }
    .btn-cancel {
      background: #e5e7eb;
      color: #1f2937;
    }
    .btn-delete {
      background: #ef4444;
      color: white;
    }
  </style>
</head>
<body>
  <div id="items">
    <div class="item">
      Item 1
      <button class="delete-btn" data-id="1">Delete</button>
    </div>
  </div>

  <div id="confirmModal" class="modal">
    <div class="modal-content">
      <h2>Confirm Delete</h2>
      <p>Are you sure you want to delete this item? This action cannot be undone.</p>
      <div class="modal-buttons">
        <button class="btn-cancel" id="cancelBtn">Cancel</button>
        <button class="btn-delete" id="confirmBtn">Delete</button>
      </div>
    </div>
  </div>

  <script>
    let pendingDeleteId = null;

    document.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        pendingDeleteId = e.target.dataset.id;
        document.getElementById('confirmModal').classList.add('active');
      });
    });

    document.getElementById('cancelBtn').addEventListener('click', () => {
      document.getElementById('confirmModal').classList.remove('active');
      pendingDeleteId = null;
    });

    document.getElementById('confirmBtn').addEventListener('click', () => {
      if (pendingDeleteId) {
        // Delete the item
        document.querySelector(`[data-id="${pendingDeleteId}"]`).closest('.item').remove();
        document.getElementById('confirmModal').classList.remove('active');
        pendingDeleteId = null;
      }
    });
  </script>
</body>
</html>
```

## React Approach

```jsx
import { useState } from 'react';

function ItemList() {
  const [items, setItems] = useState([
    { id: 1, name: 'Item 1' },
    { id: 2, name: 'Item 2' },
  ]);
  const [showModal, setShowModal] = useState(false);
  const [pendingDeleteId, setPendingDeleteId] = useState(null);

  const handleDeleteClick = (id) => {
    setPendingDeleteId(id);
    setShowModal(true);
  };

  const confirmDelete = () => {
    setItems(items.filter(item => item.id !== pendingDeleteId));
    setShowModal(false);
    setPendingDeleteId(null);
  };

  return (
    <>
      <div>
        {items.map(item => (
          <div key={item.id}>
            {item.name}
            <button onClick={() => handleDeleteClick(item.id)}>Delete</button>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="modal active">
          <div className="modal-content">
            <h2>Confirm Delete</h2>
            <p>Are you sure you want to delete this item?</p>
            <div className="modal-buttons">
              <button 
                className="btn-cancel"
                onClick={() => setShowModal(false)}
              >
                Cancel
              </button>
              <button 
                className="btn-delete"
                onClick={confirmDelete}
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default ItemList;
```

Both examples:
- Show a modal overlay when delete is clicked
- Store the pending item ID
- Only delete if confirmed
- Close on cancel or outside click (add that if needed)

Pick whichever matches your tech stack.
